from django.http import JsonResponse
from django.views.decorators.http import require_http_methods
from django.shortcuts import render
from django.conf import settings
from dialogflow_lite.dialogflow import Dialogflow

import json


def convert(data):
    if isinstance(data, bytes):
        return data.decode('ascii')
    if isinstance(data, dict):
        return dict(map(convert, data.items()))
    if isinstance(data, tuple):
        return map(convert, data)

    return data


@require_http_methods(['GET'])
def index_view(request):
    return render(request, 'app.html')


@require_http_methods(['POST'])
def chat_view(request):
    dialogflow = Dialogflow(**settings.DIALOGFLOW)
    input_dict = convert(request.body)
    input_text = json.loads(input_dict)['text']
    responses = dialogflow.text_request(str(input_text))

    if request.method == "GET":
        # Return a method not allowed response
        data = {
            'detail': 'You should make a POST request to this endpoint.',
            'name': '/chat'
        }
        return JsonResponse(data, status=405)
    elif request.method == "POST":
        data = {
            'text': responses[0],
        }
        return JsonResponse(data, status=200)
    elif request.method == "PATCH":
        data = {
            'detail': 'You should make a POST request to this endpoint.',
            'name': '/chat'
        }

        # Return a method not allowed response
        return JsonResponse(data, status=405)

    elif request.method == "DELETE":
        data = {
            'detail': 'You should make a POST request to this endpoint.',
            'name': '/chat'
        }

        # Return a method not allowed response
        return JsonResponse(data, status=405)

import json
from django.test import TestCase
from dialogflow_lite import dialogflow
from mock import Mock
from django.core.urlresolvers import reverse


class MockResponse(object):
    def __init__(self, status_code, data):
        self.status_code = status_code
        self.data = data

    def json(self):
        return self.data


def mock_get_response(*args, **kwargs):
    url = kwargs['url']
    endpoints = {
        'https://api.dialogflow.com/v1/query': MockResponse(200, {
            "id": "b340a1f7-abee-4e13-9bdd-5e8938a48b7d",
            "timestamp": "2017-02-09T15:38:26.548Z",
            "lang": "en",
            "result": {
                "source": "agent",
                "resolvedQuery": "my name is Sam and I live in Paris",
                "action": "greetings",
                "actionIncomplete": "false",
                "parameters": {},
                "contexts": [],
                "metadata": {
                  "intentId": "9f41ef7c-82fa-42a7-9a30-49a93e2c14d0",
                  "webhookUsed": "false",
                  "webhookForSlotFillingUsed": "false",
                  "intentName": "greetings"
                },
                "fulfillment": {
                    "speech": "Hi Sam! Nice to meet you!",
                    "messages": [
                        {
                            "type": 0,
                            "speech": "Hi Sam! Nice to meet you!"
                        }
                    ]
                },
                "score": 1
            },
            "status": {
                "code": 200,
                "errorType": "success"
            },
            "sessionId": "4b6a6779-b8ea-4094-b2ed-a302ba201815"
        })
    }

    return endpoints[url]


class ViewTestCase(TestCase):

    def setUp(self):
        super(ViewTestCase, self).setUp()
        self.url = reverse('index')

    def test_get_main_page(self):
        """
        Test that the index page can be loaded.
        """
        response = self.client.get(self.url)
        self.assertEqual(response.status_code, 200)


class ApiTestCase(TestCase):
    """
    Tests to make sure that the django_dialogflow API working fine
    """

    def setUp(self):
        super(ApiTestCase, self).setUp()
        dialogflow.requests.Session.get = Mock(side_effect=mock_get_response)
        self.api_url = reverse('chat')

    def test_post(self):
        """
        Test that a response is returned.
        """
        data = {
            'text': 'How are you?'
        }
        response = self.client.post(
            self.api_url,
            data=json.dumps(data),
            content_type='application/json',
            format='json'
        )

        self.assertEqual(response.status_code, 200)
        self.assertIn('text', str(response.content))

from django.db import models
from django.utils import timezone


class Statement(models.Model):
    text = models.CharField(max_length=400)

    def __str__(self):
        if len(self.text.strip()) > 60:
            return '{}...'.format(self.text[:57])
        elif len(self.text.strip()) > 0:
            return self.text

        return '<empty>'


class Response(models.Model):
    statement = models.ForeignKey(Statement, on_delete=models.CASCADE)
    response = models.CharField(max_length=400)

    created_at = models.DateTimeField(
        default=timezone.now,
        help_text='The date and time that this statement was created at.'
    )

    created_at = models.DateTimeField(
        default=timezone.now,
        help_text='The date and time that this response was created at.'
    )

    def __str__(self):
        statement = self.statement.text
        response = self.response
        return '{} => {}'.format(
            statement if len(statement) <= 20 else statement[:17] + '...',
            response if len(response) <= 40 else response[:37] + '...'
        )
